CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connected_accounts(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),platform TEXT NOT NULL,external_id TEXT,display_name TEXT,access_token_enc TEXT,refresh_token_enc TEXT,expires_at INTEGER,scopes TEXT,UNIQUE(user_id,platform));
CREATE TABLE IF NOT EXISTS videos(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),file_name TEXT NOT NULL,public_token TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING_APPROVAL',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS video_metadata(video_id INTEGER PRIMARY KEY REFERENCES videos(id),title TEXT,description TEXT,tags TEXT,hashtags TEXT);
CREATE TABLE IF NOT EXISTS approval_requests(id INTEGER PRIMARY KEY,video_id INTEGER NOT NULL REFERENCES videos(id),platform TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING_APPROVAL',visibility TEXT DEFAULT 'private',scheduled_at INTEGER,decided_at TEXT,UNIQUE(video_id,platform));
CREATE TABLE IF NOT EXISTS publishing_jobs(id INTEGER PRIMARY KEY,video_id INTEGER NOT NULL REFERENCES videos(id),platform TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'QUEUED',run_at INTEGER NOT NULL,error TEXT,UNIQUE(video_id,platform));
CREATE TABLE IF NOT EXISTS publishing_history(id INTEGER PRIMARY KEY,video_id INTEGER NOT NULL REFERENCES videos(id),user_id INTEGER NOT NULL,platform TEXT NOT NULL,post_id TEXT NOT NULL,post_url TEXT NOT NULL,published_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(video_id,platform));
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY,user_id INTEGER,action TEXT,detail TEXT,ip TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
